function wrapRasterLogoInSvg(rasterDataUri: string): string {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 44 44"><image href="${rasterDataUri}" width="44" height="44" preserveAspectRatio="xMidYMid meet"/></svg>`;
  return `data:image/svg+xml;base64,${btoa(svg)}`;
}

export const MCP_BRAND_LOGOS: Readonly<Record<string, string>> =
  Object.fromEntries(
    Object.entries(RAW_MCP_BRAND_LOGOS).map(([key, dataUri]) => [
      key,
      dataUri.startsWith('data:image/svg+xml;base64,')
        ? dataUri
        : wrapRasterLogoInSvg(dataUri),
    ]),
  );

const SVG_DATA_URI_PREFIX = 'data:image/svg+xml;base64,';

/**
 * These bundled glyphs are white, black, or near-black once their authored
 * backing is removed. Keep the original contrasting artwork in prompt rows
 * as well as catalog tiles. Colored floating marks retain their existing
 * treatment; no inversion or recoloring changes their brand colors.
 */
const FLOATING_MARKS_REQUIRING_BACKING = new Set([
  'airtable',
  'atlassian',
  'attio',
  'autodesk-product-help',
  'brex',
  'clickhouse',
  'dropbox',
  'economic-index',
  'elevenlabs',
  'frontify',
  'github',
  'granola',
  'have-i-been-pwned',
  'ifttt',
  'intercom',
  'linear',
  'lucid',
  'mercury',
  'mermaid-chart',
  'mixpanel',
  'notion',
  'openai',
  'planetscale',
  'posthog',
  'railway',
  'ramp',
  'resend',
  'roam-research',
  'sanity',
  'sentry',
  'spotify',
  'strava',
  'stripe',
  'ticket-tailor',
  'tldraw',
  'todoist',
  'uber',
  'uber-eats',
  'v0',
  'vercel',
  'webex-meetings',
  'webflow',
  'workos',
  'zapier',
]);

/**
 * Prompt rows need the brand glyph without the extended catalog artwork's
 * baked-in disc. Original 24-unit marks lose their full-canvas background;
 * composed 44-unit assets are reframed to their inner 24-unit glyph and lose
 * the outer circle entirely.
 */
export const MCP_FLOATING_BRAND_LOGOS: Readonly<Record<string, string>> =
  Object.fromEntries(
    Object.entries(MCP_BRAND_LOGOS).map(([key, dataUri]) => {
      if (
        FLOATING_MARKS_REQUIRING_BACKING.has(key) ||
        !dataUri.startsWith(SVG_DATA_URI_PREFIX)
      ) {
        return [key, dataUri];
      }
      const svg = atob(dataUri.slice(SVG_DATA_URI_PREFIX.length));
      if (svg.includes('viewBox="0 0 24 24"')) {
        const floatingSvg = svg.replace(
          /<rect\b[^>]*\bwidth="24"[^>]*\bheight="24"[^>]*\/>/,
          '',
        );
        return [key, `${SVG_DATA_URI_PREFIX}${btoa(floatingSvg)}`];
      }
      if (
        !svg.includes('viewBox="0 0 44 44"') ||
        !/<circle\b[^>]*\br="22"[^>]*\/>/.test(svg)
      ) {
        return [key, dataUri];
      }
      const floatingSvg = svg
        .replace(/<circle\b[^>]*\br="22"[^>]*\/>/, '')
        .replace('viewBox="0 0 44 44"', 'viewBox="10 10 24 24"');
      return [key, `${SVG_DATA_URI_PREFIX}${btoa(floatingSvg)}`];
    }),
  );
